        "titolo_orig": "Vertice fiume con Marina, Tajani è un leader a metà",
        "testo_it": "Italia: vertice Marina-Tajani, Forza Italia in stallo.",
        "priorita": "Bassa",
        "id_gruppo": 24,
        "link": "https://ilmanifesto.it/vertice-fiume-con-marina-tajani-e-un-leader-a-meta",
        "orario": "00:06",
